<?php
require __DIR__.'/../src/Web.php';
$a=requireAuth();$id=(int)($_GET['id']??0);$c=db();
$p=one($c,'SELECT p.id,p.title,p.slug,t.name topic,l.name level,pv.id version_id,pv.version_no,pv.statement,pv.input_desc,pv.output_desc,pv.sample_input,pv.sample_output,pv.time_limit_ms,pv.memory_limit_mb,sv.version_no suite_no
 FROM problems p JOIN topics t ON t.id=p.topic_id JOIN levels l ON l.id=p.level_id JOIN problem_versions pv ON pv.id=p.current_version_id
 JOIN test_suite_versions sv ON sv.id=p.current_suite_id WHERE p.published=true AND p.id=$1',[$id]);
if (!$p) failure('Không tìm thấy bài',404);
$drafts=rows($c,'SELECT language,code FROM drafts WHERE user_id=$1 AND problem_id=$2',[$a['id'],$id]);
$draftMap=[];foreach($drafts as $d)$draftMap[$d['language']]=$d['code'];
$history=rows($c,'SELECT s.id,r.status,r.verdict,r.passed_count,r.total_count,s.created_at FROM submissions s JOIN judging_runs r ON r.id=s.latest_run_id WHERE s.user_id=$1 AND s.problem_id=$2 ORDER BY s.id DESC LIMIT 6',[$a['id'],$id]);
layoutStart($p['title']); ?>
<div class="subhead"><a href="/">← Danh sách bài tập</a><div class="subtags"><span class="chip"><?=h($p['topic'])?></span><span class="chip"><?=h($p['level'])?></span><span class="chip">Đề v<?=h($p['version_no'])?> · Tests v<?=h($p['suite_no'])?></span></div></div>
<h1 class="page-title"><?=h($p['title'])?></h1>
<div class="workspace"><article class="panel details"><h2><span class="indexno">01</span> Đề bài</h2><p class="preserve"><?=h($p['statement'])?></p><h3>Dữ liệu vào</h3><p class="preserve"><?=h($p['input_desc'])?></p><h3>Dữ liệu ra</h3><p class="preserve"><?=h($p['output_desc'])?></p><div class="spec"><span>⏱ Giới hạn <?=h($p['time_limit_ms'])?> ms</span><span>▣ Bộ nhớ <?=h($p['memory_limit_mb'])?> MB</span></div><h3>Ví dụ công khai</h3><p class="code-label">Input</p><pre><?=h($p['sample_input'])?></pre><p class="code-label">Output</p><pre><?=h($p['sample_output'])?></pre><p class="note">Các test case ẩn không được gửi tới trình duyệt. Chấm đúng chỉ có nghĩa là vượt qua bộ ca thử.</p></article>
<section class="panel editor" data-problem="<?=h($p['id'])?>" data-csrf="<?=h(csrf())?>" id="editor"><div class="editor-head"><h2><span class="indexno">02</span> Viết lời giải</h2><select id="language"><option value="python">Python 3.12</option><option value="cpp">C++17</option></select></div><textarea spellcheck="false" id="code" aria-label="Soạn mã lập trình"></textarea><div class="actionbar"><button id="save" class="btn secondary" type="button">Lưu bản nháp</button><button id="try" class="btn secondary" type="button">▶ Chạy thử</button><button id="submit" class="btn" type="button">Nộp bài →</button></div><label class="field-label">Dữ liệu chạy thử (stdin)</label><textarea id="stdin" rows="4" placeholder="Nhập dữ liệu cho chương trình..."><?=h($p['sample_input'])?></textarea><div id="console" class="console" aria-live="polite">Kết quả chạy thử sẽ hiện tại đây.</div><p id="editor-status" class="tiny muted" aria-live="polite"></p></section></div>
<section class="section-title"><h2>Bài nộp gần đây</h2></section><div class="table-holder"><table><thead><tr><th>ID</th><th>Thời gian</th><th>Trạng thái</th><th>Kết quả</th><th>Qua test</th><th></th></tr></thead><tbody><?php foreach($history as $s): ?><tr><td>#<?=h($s['id'])?></td><td><?=h($s['created_at'])?></td><td><?=h($s['status'])?></td><td><span class="chip verdict"><?=h($s['verdict']??'Đang chấm')?></span></td><td><?=h($s['passed_count'])?>/<?=h($s['total_count'])?></td><td><a href="/submission.php?id=<?=h($s['id'])?>">Chi tiết →</a></td></tr><?php endforeach; ?></tbody></table><?php if (!$history): ?><p class="muted" style="padding:16px">Chưa có bài nộp.</p><?php endif; ?></div>
<script type="application/json" id="drafts"><?=json_encode($draftMap,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_INVALID_UTF8_SUBSTITUTE)?></script>
<?php layoutEnd(); ?>
